'use strict';

const crypto = require('node:crypto');
const { fields, array, text, identifier, publicHttps } = require('./validation.cjs');

const SELECT_KEYS = new Set(['task', 'globalPause', 'appReady', 'quota', 'humanStartedOnly']);
const HANDOFF_KEYS = new Set(['requestId', 'objective', 'sources', 'acceptance', 'stopCondition', 'timeBoundMinutes']);
const TASKS = new Set(['browser', 'research']);
const QUOTAS = new Set(['ready', 'exhausted', 'unknown']);
const GUARDS = Object.freeze([
  'Use only the named public HTTPS sources.',
  'Do not send messages, deploy, publish, purchase, change accounts, or access secrets.',
  'Do not start recurring or background work.',
  'Do not delegate beyond the coordinator-assigned packet.',
  'Return evidence candidates for local verification; never grant acceptance.',
]);

function selectBrowserFeature(input) {
  const source = fields(input, 'input', SELECT_KEYS);
  const task = source.get('task'), quota = source.get('quota'), humanStartedOnly = source.get('humanStartedOnly');
  if (!TASKS.has(task)) throw new TypeError('input.task: invalid');
  if (typeof source.get('globalPause') !== 'boolean' || typeof source.get('appReady') !== 'boolean') throw new TypeError('input pause/readiness: boolean required');
  if (!QUOTAS.has(quota)) throw new TypeError('input.quota: invalid');
  if (humanStartedOnly !== true && humanStartedOnly !== false && humanStartedOnly !== 'unknown') throw new TypeError('input.humanStartedOnly: invalid');
  const result = (status, reason) => ({ schema: 'agent-workbench-browser-selection-v1', feature: 'public-browser-assistant', status, action: status === 'eligible' ? 'prepare-public-handoff' : 'wait', reason, autostart: false, executed: false });
  if (source.get('globalPause')) return result('wait', 'global pause');
  if (!source.get('appReady')) return result('setup-required', 'browser assistant readiness is not caller-attested');
  if (quota !== 'ready') return result('wait', `quota=${quota}`);
  if (humanStartedOnly !== true) return result('wait', 'human-started-only state must be known true');
  return result('eligible', 'fresh caller-attested on-demand public handoff is eligible');
}

function buildPublicHandoff(input) {
  const source = fields(input, 'input', HANDOFF_KEYS);
  const requestId = identifier(source.get('requestId'), 'input.requestId');
  const objective = text(source.get('objective'), 'input.objective', 1000);
  const sources = array(source.get('sources'), 'input.sources', 5, 1).map((item, index) => publicHttps(item, `input.sources[${index}]`));
  const acceptance = array(source.get('acceptance'), 'input.acceptance', 5, 1).map((item, index) => text(item, `input.acceptance[${index}]`, 200));
  const stopCondition = text(source.get('stopCondition'), 'input.stopCondition', 200);
  const timeBoundMinutes = source.get('timeBoundMinutes');
  if (!Number.isInteger(timeBoundMinutes) || timeBoundMinutes < 1 || timeBoundMinutes > 15) throw new TypeError('input.timeBoundMinutes: invalid');
  const publicInputs = { requestId, objective, sources, acceptance, stopCondition, timeBoundMinutes };
  const binding = { schema: 'agent-workbench-public-handoff-v1', publicInputs, guards: GUARDS.slice() };
  const packetHash = crypto.createHash('sha256').update(JSON.stringify(binding)).digest('hex');
  const prompt = [
    `Request ID: ${requestId}`, `Objective: ${objective}`, `Public sources:\n${sources.map(item => `- ${item}`).join('\n')}`,
    `Acceptance:\n${acceptance.map(item => `- ${item}`).join('\n')}`, `Stop condition: ${stopCondition}`, `Time bound: ${timeBoundMinutes} minutes`,
    `Immutable guards:\n${GUARDS.map(item => `- ${item}`).join('\n')}`, `Return binding: requestId=${requestId}; packetHash=${packetHash}`,
    'Return a compact candidate with findings, source pointers, limitations, and any artifact hashes actually observed.',
  ].join('\n\n');
  if (prompt.length > 6000) throw new TypeError('handoff prompt exceeds bound');
  return { schema: 'agent-workbench-public-handoff-v1', status: 'prepared', dispatched: false, executed: false, requestId, packetHash, prompt, publicInputs, guards: GUARDS.slice(), autonomousRecurringWork: false };
}

module.exports = { selectBrowserFeature, buildPublicHandoff };

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { listRoles, routeTask, selectCapability, selectBrowserFeature, buildPublicHandoff } = require('../lib/index.cjs');

const slots = () => ({ external: { state: 'ready', busy: false, capabilities: ['external-worker'] }, native: { state: 'ready', running: 0, capacity: 2, capabilities: ['lead-reviewer', 'native-analyst', 'native-coder', 'native-small'] } });
const route = (extra = {}) => ({ schema: 'agent-workbench-route-input-v1', requestId: 'request-1', roleId: 'workbench-research', objective: 'Inspect the bounded input.', inputClass: 'public', workType: 'research', globalPause: false, externalBusy: false, readiness: { observedAt: '2026-09-13T12:00:00.000Z', now: '2026-09-13T12:01:00.000Z', appReady: true, quota: 'ready', humanStartedOnly: true }, sources: ['https://example.com/release'], selection: { complexity: 'small', deterministic: false, priorFailures: 0, accountSlots: slots() }, ...extra });
const capability = (extra = {}) => ({ kind: 'code', complexity: 'medium', requiresHostTools: false, deterministic: false, priorFailures: 0, globalPause: false, externalBusy: false, accountSlots: slots(), acceptance: ['Preserve the contract.'], ...extra });

test('lists four neutral role and catalog identifiers', () => {
  const out = listRoles(); assert.equal(out.roles.length, 4); assert.deepEqual(out.roles.map(item => item.catalogId), ['research', 'systems', 'design', 'critic']); assert.equal(out.finalReviewerCapability, 'lead-reviewer');
});
test('eligible public research prepares a bounded handoff without dispatch', () => {
  const out = routeTask(route()); assert.equal(out.transport, 'public-browser-handoff'); assert.equal(out.executed, false); assert.equal(out.handoff.dispatched, false); assert.match(out.handoff.prompt, /example\.com/);
});
test('all four roles can receive eligible public browser work', () => {
  for (const roleId of ['workbench-research', 'workbench-systems', 'workbench-design', 'workbench-critic']) assert.equal(routeTask(route({ roleId, workType: 'browser' })).status, 'prepared');
});
test('public code uses the explicit external capability slot', () => {
  const out = routeTask(route({ roleId: 'workbench-systems', workType: 'code', sources: [] })); assert.equal(out.selection.selected.capabilityId, 'external-worker'); assert.equal(out.requiresSourceBindings, true);
});
test('private input cannot consume external quota and selects native analysis', () => {
  const out = routeTask(route({ inputClass: 'private', roleId: 'workbench-critic', workType: 'audit', sources: [] })); assert.equal(out.selection.selected.capabilityId, 'native-analyst'); assert.equal(out.selection.accountSlots.external.state, 'unavailable');
});
test('private input waits when native capability is unavailable', () => {
  const accountSlots = slots(); accountSlots.native.state = 'unknown'; const out = routeTask(route({ inputClass: 'private', workType: 'code', sources: [], selection: { complexity: 'small', deterministic: false, priorFailures: 0, accountSlots } })); assert.equal(out.status, 'wait'); assert.equal(out.transport, null);
});
test('stale, paused, busy, and unknown quota public gates fail closed', () => {
  assert.equal(routeTask(route({ readiness: { ...route().readiness, now: '2026-09-13T12:06:00.001Z' } })).status, 'wait');
  assert.equal(routeTask(route({ globalPause: true })).status, 'wait');
  assert.equal(routeTask(route({ externalBusy: true })).status, 'wait');
  assert.equal(routeTask(route({ readiness: { ...route().readiness, quota: 'unknown' } })).status, 'wait');
  const accountSlots = slots(); accountSlots.external.state = 'unknown'; assert.equal(routeTask(route({ selection: { complexity: 'small', deterministic: false, priorFailures: 0, accountSlots } })).status, 'wait');
});
test('two failed public attempts stop for lead-reviewer diagnosis', () => {
  const out = routeTask(route({ selection: { complexity: 'small', deterministic: false, priorFailures: 2, accountSlots: slots() } })); assert.equal(out.status, 'wait'); assert.match(out.reason, /lead-reviewer/);
});
test('browser selector requires caller-attested human start', () => {
  const out = selectBrowserFeature({ task: 'research', globalPause: false, appReady: true, quota: 'ready', humanStartedOnly: 'unknown' }); assert.equal(out.status, 'wait'); assert.equal(out.autostart, false);
});
test('public handoff rejects credentials and private hosts', () => {
  const base = { requestId: 'public-1', objective: 'Inspect.', sources: ['https://example.com'], acceptance: ['Cite evidence.'], stopCondition: 'Stop.', timeBoundMinutes: 5 };
  assert.throws(() => buildPublicHandoff({ ...base, sources: ['https://user:pass@example.com'] }), /public HTTPS/);
  assert.throws(() => buildPublicHandoff({ ...base, sources: ['https://127.0.0.1'] }), /public host/);
  for (const url of ['https://[::1]', 'https://[fc00::1]', 'https://[fe80::1]', 'https://[2001:db8::1]', 'https://[::ffff:127.0.0.1]', 'https://localhost.', 'https://sub.localhost.', 'https://printer.local.', 'https://localhost..', 'https://example.com..']) assert.throws(() => buildPublicHandoff({ ...base, sources: [url] }), /public host/);
  assert.equal(buildPublicHandoff({ ...base, sources: ['https://example.com.'] }).status, 'prepared');
});
test('route objective bound leaves room for every role wrapper', () => {
  for (const roleId of ['workbench-research', 'workbench-systems', 'workbench-design', 'workbench-critic']) assert.equal(routeTask(route({ roleId, objective: 'x'.repeat(500) })).status, 'prepared');
  assert.throws(() => routeTask(route({ objective: 'x'.repeat(501) })), /invalid string/);
});
test('review and repeated failures never downgrade from lead reviewer', () => {
  assert.equal(selectCapability(capability({ kind: 'review' })).selected.capabilityId, 'lead-reviewer'); assert.equal(selectCapability(capability({ priorFailures: 2 })).selected.capabilityId, 'lead-reviewer');
});
test('large code is lead-reviewed and deterministic work stays local', () => {
  assert.equal(selectCapability(capability({ complexity: 'large' })).selected.capabilityId, 'lead-reviewer'); assert.equal(selectCapability(capability({ deterministic: true })).action, 'local');
});
test('explicit slot capacity and global pause are honored', () => {
  const full = slots(); full.native.running = 2; full.external.state = 'unavailable'; assert.equal(selectCapability(capability({ accountSlots: full })).action, 'wait'); assert.equal(selectCapability(capability({ globalPause: true })).action, 'wait');
});
test('non-string role identifiers and accessors are rejected without coercion', () => {
  let calls = 0; const roleId = { toString() { calls += 1; return 'workbench-research'; } }; assert.throws(() => routeTask(route({ roleId })), /unknown role/); assert.equal(calls, 0);
  const input = route(); Object.defineProperty(input, 'roleId', { get() { calls += 1; return 'workbench-research'; } }); assert.throws(() => routeTask(input), /accessor/); assert.equal(calls, 0);
});
test('proxies and over-limit capability arrays are rejected before traversal', () => {
  assert.throws(() => routeTask(new Proxy(route(), {})), /proxy/); const accountSlots = slots(); accountSlots.native.capabilities = Array(100000); assert.throws(() => routeTask(route({ selection: { complexity: 'small', deterministic: false, priorFailures: 0, accountSlots } })), /bound/);
});
test('worker prompt contains the fixed role acceptance criteria', () => {
  const out = routeTask(route({ workType: 'code', sources: [] })); for (const criterion of out.role.acceptance) assert.match(out.packetTemplate.prompt, new RegExp(criterion.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')));
});

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { planTeam, advanceTeam } = require('../lib/index.cjs');
const sha = value => value.repeat(64);
const plan = (extra = {}) => ({ schema: 'agent-workbench-plan-input-v1', teamId: 'team-1', now: '2026-09-13T12:00:00.000Z', deadlineAt: '2026-09-13T12:25:00.000Z', maxTurns: 8, maxPeerHops: 2, sourceBindings: [{ id: 'contract', sha256: sha('a') }], acceptance: ['Evidence is bound.'], tasks: [{ id: 'first', ownerRoleId: 'workbench-research', objective: 'Collect evidence.', dependsOn: [] }, { id: 'second', ownerRoleId: 'workbench-critic', objective: 'Challenge it.', dependsOn: ['first'] }], ...extra });
function act(state, action, overrides = {}) { return advanceTeam({ schema: 'agent-workbench-advance-input-v1', state, expectedRevision: state.revision, expectedStateFingerprint: state.stateFingerprint, now: '2026-09-13T12:05:00.000Z', action, ...overrides }); }
function binding(state, type, taskId, extra = {}) { return { type, taskId, sourceFingerprint: state.sourceFingerprint, criteriaFingerprint: state.criteriaFingerprint, ...extra }; }
function dispatch(state, taskId = 'first', dispatchId = 'dispatch-1', actorRoleId = 'workbench-research') { return act(state, binding(state, 'dispatch', taskId, { actorRoleId, dispatchId })).state; }

test('plan is deeply frozen and binds sources, criteria, and DAG', () => {
  const state = planTeam(plan()); assert.equal(Object.isFrozen(state), true); assert.equal(Object.isFrozen(state.tasks), true); assert.equal(Object.isFrozen(state.tasks[1].dependsOn), true); assert.match(state.planFingerprint, /^[a-f0-9]{64}$/); assert.equal(state.runtimeAccepted, false);
});
test('cycle, unknown dependency, and unknown owner are rejected', () => {
  assert.throws(() => planTeam(plan({ tasks: [{ id: 'a', ownerRoleId: 'workbench-research', objective: 'A', dependsOn: ['b'] }, { id: 'b', ownerRoleId: 'workbench-critic', objective: 'B', dependsOn: ['a'] }] })), /cycle/);
  assert.throws(() => planTeam(plan({ tasks: [{ id: 'a', ownerRoleId: 'workbench-research', objective: 'A', dependsOn: ['missing'] }] })), /unknown dependency/);
  assert.throws(() => planTeam(plan({ tasks: [{ id: 'a', ownerRoleId: 'unknown', objective: 'A', dependsOn: [] }] })), /unknown role/);
});
test('dispatch requires the owner and ready dependencies', () => {
  const state = planTeam(plan()); assert.throws(() => dispatch(state, 'second', 'dispatch-2', 'workbench-critic'), /dependencies/); assert.throws(() => dispatch(state, 'first', 'dispatch-1', 'workbench-critic'), /owner/);
});
test('same running dispatch is idempotent without spending a turn', () => {
  const running = dispatch(planTeam(plan())); const out = act(running, binding(running, 'dispatch', 'first', { actorRoleId: 'workbench-research', dispatchId: 'dispatch-1' })); assert.equal(out.changed, false); assert.equal(out.state.turnsUsed, 1); assert.equal(out.revision, 1);
  assert.throws(() => act(running, binding(running, 'dispatch', 'first', { actorRoleId: 'workbench-research', dispatchId: 'dispatch-1', sourceFingerprint: sha('f') })), /binding mismatch/);
});
test('failed dispatch IDs remain spent and reject reuse', () => {
  let state = dispatch(planTeam(plan())); state = act(state, { type: 'fail', taskId: 'first', dispatchId: 'dispatch-1', reason: 'bounded failure' }).state; assert.equal(state.spentDispatchIds.includes('dispatch-1'), true); assert.throws(() => dispatch(state), /already spent/);
});
test('late results from a failed attempt cannot attach to a retry', () => {
  let state = dispatch(planTeam(plan())); state = act(state, { type: 'fail', taskId: 'first', dispatchId: 'dispatch-1', reason: 'failed' }).state; state = dispatch(state, 'first', 'dispatch-2'); assert.throws(() => act(state, binding(state, 'result', 'first', { dispatchId: 'dispatch-1', resultHash: sha('b'), summary: 'late' })), /dispatch binding/);
});
test('two failures escalate to lead reviewer', () => {
  let state = dispatch(planTeam(plan())); state = act(state, { type: 'fail', taskId: 'first', dispatchId: 'dispatch-1', reason: 'one' }).state; state = dispatch(state, 'first', 'dispatch-2'); state = act(state, { type: 'fail', taskId: 'first', dispatchId: 'dispatch-2', reason: 'two' }).state; assert.equal(state.tasks[0].status, 'escalated'); assert.equal(state.tasks[0].escalatedTo, 'lead-reviewer');
  assert.throws(() => dispatch(state, 'first', 'dispatch-3'), /not dispatchable/);
});
test('result and acceptance require immutable binding fingerprints', () => {
  const state = dispatch(planTeam(plan())); assert.throws(() => act(state, binding(state, 'result', 'first', { dispatchId: 'dispatch-1', resultHash: sha('b'), summary: 'candidate', sourceFingerprint: sha('f') })), /binding mismatch/);
});
test('acceptance retains reviewer evidence and never grants runtime acceptance', () => {
  let state = dispatch(planTeam(plan())); state = act(state, binding(state, 'result', 'first', { dispatchId: 'dispatch-1', resultHash: sha('b'), summary: 'candidate' })).state;
  state = act(state, binding(state, 'accept', 'first', { reviewerCapability: 'lead-reviewer', reviewEvidence: { path: 'evidence/review.json', sha256: sha('c') }, coordinatorAttested: true })).state;
  assert.equal(state.tasks[0].review.coordinatorAttested, true); assert.equal(state.tasks[0].review.cryptographicallyAuthenticated, false); assert.equal(state.tasks[0].review.runtimeVerified, false); assert.equal(Object.isFrozen(state.tasks[0].review), true); assert.equal(state.runtimeAccepted, false);
});
test('a plain reviewer string or missing evidence cannot accept', () => {
  let state = dispatch(planTeam(plan())); state = act(state, binding(state, 'result', 'first', { dispatchId: 'dispatch-1', resultHash: sha('b'), summary: 'candidate' })).state;
  assert.throws(() => act(state, binding(state, 'accept', 'first', { reviewerCapability: 'reviewer', reviewEvidence: { path: 'x', sha256: sha('c') }, coordinatorAttested: true })), /attestation/);
});
test('stale revision, stale fingerprint, and expired deadline reject', () => {
  const state = planTeam(plan()); const action = binding(state, 'dispatch', 'first', { actorRoleId: 'workbench-research', dispatchId: 'dispatch-1' });
  assert.throws(() => act(state, action, { expectedRevision: 1 }), /stale/); assert.throws(() => act(state, action, { expectedStateFingerprint: sha('f') }), /stale/); assert.throws(() => act(state, action, { now: '2026-09-13T12:25:00.001Z' }), /deadline/);
});
test('tampering with source, criteria, plan, or state fingerprints rejects restored state', () => {
  const state = JSON.parse(JSON.stringify(planTeam(plan())));
  for (const change of [copy => { copy.sourceBindings[0].sha256 = sha('b'); }, copy => { copy.acceptance[0] = 'Changed.'; }, copy => { copy.tasks[0].objective = 'Changed.'; }, copy => { copy.turnsUsed = 1; }]) {
    const copy = structuredClone(state); change(copy); assert.throws(() => act(copy, { type: 'fail', taskId: 'first', dispatchId: 'x', reason: 'x' }), /fingerprint|binding/);
  }
});
test('peer hops are bounded and consume the shared turn budget', () => {
  let state = dispatch(planTeam(plan())); state = act(state, binding(state, 'result', 'first', { dispatchId: 'dispatch-1', resultHash: sha('b'), summary: 'candidate' })).state;
  state = act(state, { type: 'peer-hop', fromTaskId: 'first', toTaskId: 'second' }).state; assert.equal(state.peerHopsUsed, 1); assert.equal(state.turnsUsed, 2); assert.throws(() => act(state, { type: 'peer-hop', fromTaskId: 'first', toTaskId: 'second' }), /eligible/);
});
test('non-string restored owner is rejected without coercion', () => {
  const state = JSON.parse(JSON.stringify(planTeam(plan()))); let calls = 0; state.tasks[0].ownerRoleId = { toString() { calls += 1; return 'workbench-research'; } }; assert.throws(() => act(state, { type: 'fail', taskId: 'first', dispatchId: 'x', reason: 'x' }), /unknown role/); assert.equal(calls, 0);
});
test('accessor and proxy state inputs fail before reads', () => {
  const state = planTeam(plan()); let calls = 0; const input = { schema: 'agent-workbench-advance-input-v1', state, expectedRevision: 0, expectedStateFingerprint: state.stateFingerprint, now: '2026-09-13T12:05:00.000Z', action: {} }; Object.defineProperty(input, 'state', { get() { calls += 1; return state; } }); assert.throws(() => advanceTeam(input), /accessor/); assert.equal(calls, 0); assert.throws(() => advanceTeam(new Proxy({}, {})), /proxy/);
});

'use strict';

const { types } = require('node:util');
const { validateTeam } = require('./team-state.cjs');

const INSPECTION_SCHEMA = 'agent-workbench-team-inspection-v1';
const BRIEF_SCHEMA = 'agent-workbench-task-brief-v1';
const OPTION_KEYS = new Set(['maxConcurrent', 'now']);
const BRIEF_OPTION_KEYS = new Set(['maxBytes']);

function plainOptions(value, label, allowed) {
  if (types.isProxy(value)) throw new TypeError(`${label}: proxy rejected`);
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`${label}: plain object required`);
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null) throw new TypeError(`${label}: prototype rejected`);
  const result = new Map();
  for (const key of Reflect.ownKeys(value)) {
    if (typeof key !== 'string' || !allowed.has(key)) throw new TypeError(`${label}: unsupported field`);
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (!descriptor || !Object.hasOwn(descriptor, 'value')) throw new TypeError(`${label}.${key}: accessor rejected`);
    result.set(key, descriptor.value);
  }
  return result;
}

function canonicalInstant(value, label) {
  if (typeof value !== 'string') throw new TypeError(`${label}: canonical timestamp required`);
  const milliseconds = Date.parse(value);
  if (!Number.isFinite(milliseconds) || new Date(milliseconds).toISOString() !== value) throw new TypeError(`${label}: canonical timestamp required`);
  return { value, milliseconds };
}

function taskId(value, label) {
  if (typeof value !== 'string' || !/^[a-z0-9][a-z0-9._-]{0,79}$/i.test(value)) throw new TypeError(`${label}: invalid identifier`);
  return value;
}

function restored(state) {
  return validateTeam(state);
}

function inspectedOptions(state, value) {
  const source = plainOptions(value, 'options', OPTION_KEYS);
  const maxConcurrent = source.has('maxConcurrent') ? source.get('maxConcurrent') : 1;
  if (!Number.isInteger(maxConcurrent) || maxConcurrent < 1 || maxConcurrent > 4) throw new TypeError('options.maxConcurrent: invalid integer');
  const baseline = canonicalInstant(state.updatedAt, 'state.updatedAt');
  const now = source.has('now') ? canonicalInstant(source.get('now'), 'options.now') : baseline;
  if (now.milliseconds < baseline.milliseconds) throw new TypeError('options.now: precedes state.updatedAt');
  return { maxConcurrent, now };
}

function briefOptions(value) {
  const source = plainOptions(value, 'options', BRIEF_OPTION_KEYS);
  const maxBytes = source.has('maxBytes') ? source.get('maxBytes') : 8192;
  if (!Number.isInteger(maxBytes) || maxBytes < 256 || maxBytes > 131072) throw new TypeError('options.maxBytes: invalid integer');
  return { maxBytes };
}

function criticalPathLengths(tasks) {
  const children = new Map(tasks.map(task => [task.id, []]));
  for (const task of tasks) for (const dependency of task.dependsOn) children.get(dependency).push(task.id);
  const memo = new Map();
  function length(id) {
    if (memo.has(id)) return memo.get(id);
    const value = children.get(id).reduce((maximum, child) => Math.max(maximum, 1 + length(child)), 0);
    memo.set(id, value);
    return value;
  }
  for (const task of tasks) length(task.id);
  return memo;
}

function taskView(task, extra = {}) {
  return { id: task.id, ownerRoleId: task.ownerRoleId, ...extra };
}

function peerEvidence(task, byId) {
  if (task.peerFrom === null) return { valid: true, value: null };
  const source = byId.get(task.peerFrom);
  if (!source || !['candidate', 'accepted-candidate'].includes(source.status) || source.resultHash === null || source.candidateSummary === null) return { valid: false, reason: `peer-evidence-invalid:${task.peerFrom}` };
  return {
    valid: true,
    value: {
      id: source.id,
      ownerRoleId: source.ownerRoleId,
      objective: source.objective,
      status: source.status,
      resultHash: source.resultHash,
      candidateSummary: source.candidateSummary,
      review: source.review === null ? null : reviewReference(source.review)
    }
  };
}

function dependencyBlock(task, byId) {
  const unmet = task.dependsOn.filter(id => byId.get(id).status !== 'accepted-candidate');
  if (unmet.length) return `dependency-not-accepted:${unmet.join(',')}`;
  const peer = peerEvidence(task, byId);
  return peer.valid ? null : peer.reason;
}

function inspectTeam(state, options = {}) {
  const team = restored(state);
  const { maxConcurrent, now } = inspectedOptions(team, options);
  const deadline = canonicalInstant(team.deadlineAt, 'state.deadlineAt');
  const expired = now.milliseconds >= deadline.milliseconds;
  const byId = new Map(team.tasks.map(task => [task.id, task]));
  const order = new Map(team.tasks.map((task, index) => [task.id, index]));
  const paths = criticalPathLengths(team.tasks);
  const running = team.tasks.filter(task => task.status === 'running').map(task => taskView(task, { dispatchId: task.dispatchId }));
  const candidates = team.tasks.filter(task => task.status === 'candidate').map(task => taskView(task, { resultHash: task.resultHash, summary: task.candidateSummary }));
  const escalated = team.tasks.filter(task => task.status === 'escalated').map(task => taskView(task, { failures: task.failures, escalatedTo: task.escalatedTo }));
  const freeCapacity = Math.max(0, maxConcurrent - running.length);
  const remaining = { turns: team.maxTurns - team.turnsUsed, peerHops: team.maxPeerHops - team.peerHopsUsed };
  const blocked = [];
  const ready = [];
  for (const task of team.tasks) {
    if (task.status !== 'pending') continue;
    const dependencyReason = dependencyBlock(task, byId);
    if (expired) blocked.push(taskView(task, { reason: 'deadline-exceeded' }));
    else if (remaining.turns === 0) blocked.push(taskView(task, { reason: 'turn-budget-exhausted' }));
    else if (dependencyReason) blocked.push(taskView(task, { reason: dependencyReason }));
    else ready.push(task);
  }
  ready.sort((left, right) => paths.get(right.id) - paths.get(left.id) || order.get(left.id) - order.get(right.id) || left.id.localeCompare(right.id));
  const scheduleLimit = Math.min(freeCapacity, remaining.turns);
  const schedule = ready.slice(0, scheduleLimit).map(task => taskView(task, { objective: task.objective, dependsOn: task.dependsOn.slice(), criticalPathLength: paths.get(task.id) }));
  const overflowReason = remaining.turns < freeCapacity ? 'turn-budget-exhausted' : 'concurrency-capacity-exhausted';
  for (const task of ready.slice(scheduleLimit)) blocked.push(taskView(task, { reason: overflowReason }));
  return {
    schema: INSPECTION_SCHEMA,
    teamId: team.teamId,
    revision: team.revision,
    stateFingerprint: team.stateFingerprint,
    now: now.value,
    maxConcurrent,
    activeCount: running.length,
    freeCapacity,
    remaining,
    schedule,
    running,
    candidates,
    escalated,
    blocked
  };
}

function reviewReference(review) {
  return {
    reviewerCapability: review.reviewerCapability,
    evidencePath: review.evidencePath,
    evidenceSha256: review.evidenceSha256,
    coordinatorAttested: review.coordinatorAttested,
    runtimeVerified: review.runtimeVerified
  };
}

function buildTaskBrief(state, requestedTaskId, options = {}) {
  const team = restored(state);
  const id = taskId(requestedTaskId, 'taskId');
  const { maxBytes } = briefOptions(options);
  const task = team.tasks.find(item => item.id === id);
  if (!task) throw new TypeError('taskId: unknown task');
  const byId = new Map(team.tasks.map(item => [item.id, item]));
  const unmet = task.dependsOn.filter(dependency => byId.get(dependency).status !== 'accepted-candidate');
  if (unmet.length) return { ok: false, status: 'dependencies-unaccepted', taskId: id, blockedDependencies: unmet.map(dependency => ({ id: dependency, status: byId.get(dependency).status })) };
  const peer = peerEvidence(task, byId);
  if (!peer.valid) return { ok: false, status: 'peer-evidence-invalid', taskId: id, peerFrom: task.peerFrom };
  const dependencies = task.dependsOn.map(dependency => {
    const item = byId.get(dependency);
    return {
      id: item.id,
      ownerRoleId: item.ownerRoleId,
      objective: item.objective,
      resultHash: item.resultHash,
      candidateSummary: item.candidateSummary,
      review: reviewReference(item.review)
    };
  });
  const payload = {
    ok: true,
    schema: BRIEF_SCHEMA,
    teamId: team.teamId,
    revision: team.revision,
    stateFingerprint: team.stateFingerprint,
    updatedAt: team.updatedAt,
    deadlineAt: team.deadlineAt,
    remaining: { turns: team.maxTurns - team.turnsUsed, peerHops: team.maxPeerHops - team.peerHopsUsed },
    task: { id: task.id, ownerRoleId: task.ownerRoleId, objective: task.objective },
    sourceBindings: team.sourceBindings.map(binding => ({ id: binding.id, sha256: binding.sha256 })),
    sourceFingerprint: team.sourceFingerprint,
    criteriaFingerprint: team.criteriaFingerprint,
    acceptance: team.acceptance.slice(),
    dependencies,
    peerEvidence: peer.value
  };
  const requiredBytes = Buffer.byteLength(JSON.stringify(payload), 'utf8');
  if (requiredBytes > maxBytes) return { ok: false, status: 'brief-too-large', taskId: id, requiredBytes, maxBytes };
  return { ...payload, bytes: requiredBytes };
}

module.exports = { inspectTeam, buildTaskBrief };

