'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const { planTeam, advanceTeam, validateTeam, replayTeam } = require('../lib/index.cjs');
const { runReleaseLab } = require('../examples/release-lab.cjs');

const START_MS = Date.parse('2026-09-13T12:00:00.000Z');
const packageRoot = path.resolve(__dirname, '..'), cli = path.join(packageRoot, 'bin/workbench.cjs');
const at = seconds => new Date(START_MS + seconds * 1000).toISOString();
const hash = value => crypto.createHash('sha256').update(String(value)).digest('hex');
const objectHash = value => crypto.createHash('sha256').update(typeof value === 'string' ? value : JSON.stringify(value)).digest('hex');
const roles = ['workbench-research', 'workbench-systems', 'workbench-design', 'workbench-critic'];
const simpleTasks = () => [
  { id: 'first', ownerRoleId: roles[0], objective: 'Collect evidence.', dependsOn: [] },
  { id: 'second', ownerRoleId: roles[3], objective: 'Challenge it.', dependsOn: ['first'] }
];
const makePlan = (tasks = simpleTasks(), extra = {}) => ({
  schema: 'agent-workbench-plan-input-v1',
  teamId: 'stress-team',
  now: at(0),
  deadlineAt: at(25 * 60),
  maxTurns: 24,
  maxPeerHops: 4,
  sourceBindings: [{ id: 'contract', sha256: hash('contract-v1') }],
  acceptance: ['Every result retains its current evidence bindings.'],
  tasks,
  ...extra
});
const binding = state => ({ sourceFingerprint: state.sourceFingerprint, criteriaFingerprint: state.criteriaFingerprint });
function request(state, now, action, overrides = {}) {
  return {
    schema: 'agent-workbench-advance-input-v1', state,
    expectedRevision: state.revision, expectedStateFingerprint: state.stateFingerprint,
    now, action, ...overrides
  };
}
function apply(state, now, action, overrides) { return advanceTeam(request(state, now, action, overrides)); }
function dispatchAction(state, taskId, dispatchId, actorRoleId, extra = {}) {
  return { type: 'dispatch', taskId, actorRoleId, dispatchId, ...binding(state), ...extra };
}
function resultAction(state, taskId, dispatchId, label) {
  return { type: 'result', taskId, dispatchId, resultHash: hash(label), summary: `Candidate ${label}.`, ...binding(state) };
}
function reviewAction(state, type, taskId, label, extra = {}) {
  return {
    type, taskId, sourceFingerprint: state.sourceFingerprint, criteriaFingerprint: state.criteriaFingerprint,
    reviewerCapability: 'lead-reviewer', actorRoleId: 'lead-reviewer', coordinatorAttested: true,
    reviewEvidence: { path: `evidence/${label}.json`, sha256: hash(`review-${label}`) }, ...extra
  };
}
function dispatch(state, now, taskId, dispatchId, actorRoleId, extra) { return apply(state, now, dispatchAction(state, taskId, dispatchId, actorRoleId, extra)).state; }
function result(state, now, taskId, dispatchId, label) { return apply(state, now, resultAction(state, taskId, dispatchId, label)).state; }
function accept(state, now, taskId, label) { return apply(state, now, reviewAction(state, 'accept', taskId, label)).state; }
function reseal(state) {
  const copy = structuredClone(state);
  delete copy.stateFingerprint;
  function canonical(value) {
    if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
    if (value && typeof value === 'object') return `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${canonical(value[key])}`).join(',')}}`;
    return JSON.stringify(value);
  }
  const value = canonical(copy), framed = `${Buffer.byteLength(value, 'utf8')}:${value}`;
  copy.stateFingerprint = crypto.createHash('sha256').update(framed).digest('hex');
  return copy;
}

