    { id: 'b', ownerRoleId: roles[2], objective: 'B.', dependsOn: ['root'] },
    { id: 'c', ownerRoleId: roles[3], objective: 'C.', dependsOn: ['root'] },
    { id: 'd', ownerRoleId: roles[0], objective: 'D.', dependsOn: ['a', 'b'] },
    { id: 'e', ownerRoleId: roles[1], objective: 'E.', dependsOn: ['b', 'c'] },
    { id: 'f', ownerRoleId: roles[2], objective: 'F.', dependsOn: ['d'] },
    { id: 'g', ownerRoleId: roles[3], objective: 'G.', dependsOn: ['d', 'e'] },
    { id: 'h', ownerRoleId: roles[0], objective: 'H.', dependsOn: ['e'] },
    { id: 'i', ownerRoleId: roles[1], objective: 'I.', dependsOn: ['f', 'g', 'h'] },
    { id: 'independent', ownerRoleId: roles[2], objective: 'Independent.', dependsOn: [] },
    { id: 'peer', ownerRoleId: roles[3], objective: 'Peer consumer.', dependsOn: [] }
  ];
  let state = planTeam(makePlan(tasks)), tick = 1;
  state = dispatch(state, at(tick++), 'root', 'dispatch-root', roles[0]);
  state = result(state, at(tick++), 'root', 'dispatch-root', 'root');
  state = apply(state, at(tick++), { type: 'peer-hop', fromTaskId: 'root', toTaskId: 'peer', ...binding(state) }).state;
  state = accept(state, at(tick++), 'root', 'root');
  for (const taskId of ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'independent', 'peer']) {
    const owner = tasks.find(task => task.id === taskId).ownerRoleId, dispatchId = `dispatch-${taskId}`;
    state = dispatch(state, at(tick++), taskId, dispatchId, owner);
    state = result(state, at(tick++), taskId, dispatchId, taskId);
