  }
  assert.equal(state.allCandidatesAccepted, true);
  const spentBefore = state.spentDispatchIds.slice();
  const reopened = apply(state, at(tick++), reviewAction(state, 'reopen', 'root', 'reopen-root', { reason: 'Root evidence changed.' }));
  state = reopened.state;
  assert.equal(state.tasks.find(task => task.id === 'independent').status, 'accepted-candidate');
  assert.equal(state.tasks.find(task => task.id === 'peer').status, 'pending');
  assert.equal(state.tasks.find(task => task.id === 'peer').peerFrom, null);
  assert.equal(state.tasks.filter(task => task.status === 'pending').length, 11);
  assert.deepEqual(state.spentDispatchIds, spentBefore);
  assert.equal(reopened.delta.invalidated.length, 11);
  assert.equal(state.allCandidatesAccepted, false);
  assert.equal(state.runtimeAccepted, false);
});

