    [at(1), current => dispatchAction(current, 'first', 'dispatch-1', roles[0])],
    [at(2), current => resultAction(current, 'first', 'dispatch-1', 'first')],
    [at(3), current => reviewAction(current, 'accept', 'first', 'first')]
  ]) {
    const action = actionFactory(state);
    const event = { expectedRevision: state.revision, expectedStateFingerprint: state.stateFingerprint, now, action };
    events.push(event);
    state = advanceTeam({ schema: 'agent-workbench-advance-input-v1', state, ...event }).state;
