  broken[1].expectedRevision = 0;
  assert.throws(() => replayTeam({ schema: 'agent-workbench-replay-input-v1', plan, events: broken }), /stale state/);
  assert.throws(() => replayTeam({ schema: 'agent-workbench-replay-input-v1', plan, events: Array.from({ length: 201 }, () => events[0]) }), /length outside bound/);
});

test('five seeded twelve-task DAG schedules survive bounded serialized restarts', () => {
  function random(seed) {
    let value = seed >>> 0;
    return () => {
      value ^= value << 13; value ^= value >>> 17; value ^= value << 5;
      return (value >>> 0) / 0x100000000;
    };
  }
  for (const seed of [0x13579bdf, 0x2468ace0, 0xdeadbeef, 0x10203040, 0x89abcdef]) {
    const rand = random(seed), tasks = [];
    for (let index = 0; index < 12; index += 1) {
      const possible = tasks.map(task => task.id), dependencyCount = index === 0 ? 0 : Math.min(possible.length, rand() < 0.35 ? 0 : rand() < 0.75 ? 1 : 2);
      const dependsOn = [];
      while (dependsOn.length < dependencyCount) {
        const chosen = possible[Math.floor(rand() * possible.length)];
        if (!dependsOn.includes(chosen)) dependsOn.push(chosen);
      }
      tasks.push({ id: `s${String(index).padStart(2, '0')}`, ownerRoleId: roles[index % roles.length], objective: `Seed ${seed} task ${index}.`, dependsOn });
    }
    let state = planTeam(makePlan(tasks, { teamId: `seed-${seed.toString(16)}` })), tick = 1, completed = 0;
    while (!state.allCandidatesAccepted) {
      const ready = state.tasks.filter(task => task.status === 'pending' && task.dependsOn.every(id => state.tasks.find(item => item.id === id).status === 'accepted-candidate'));
      assert.ok(ready.length > 0, `seed ${seed} must have schedulable work`);
      const selected = ready[Math.floor(rand() * ready.length)], dispatchId = `dispatch-${seed.toString(16)}-${selected.id}`;
      state = dispatch(state, at(tick++), selected.id, dispatchId, selected.ownerRoleId);
      state = result(state, at(tick++), selected.id, dispatchId, `${seed}-${selected.id}`);
      state = accept(state, at(tick++), selected.id, `${seed}-${selected.id}`);
      state = validateTeam(JSON.parse(JSON.stringify(state)));
      completed += 1;
    }
    assert.equal(completed, 12);
    assert.equal(state.revision, 36);
    assert.equal(state.turnsUsed, 12);
    assert.equal(new Set(state.spentDispatchIds).size, 12);
    assert.equal(state.tasks.every(task => task.status === 'accepted-candidate'), true);
    assert.equal(state.runtimeAccepted, false);
  }
});

test('release lab independently proves the 12-task correction, evidence, restart, and replay outcome', () => {
  const imported = spawnSync(process.execPath, ['-e', "require('./examples/release-lab.cjs')"], { cwd: packageRoot, encoding: 'utf8' });
