  assert.equal(finalState.spentDispatchIds.length, 24);
  assert.equal(new Set(finalState.spentDispatchIds).size, 24);

  const descendants = new Set(['api-contract']);
  for (let changed = true; changed;) {
    changed = false;
    for (const task of plan.tasks) if (!descendants.has(task.id) && task.dependsOn.some(id => descendants.has(id))) {
      descendants.add(task.id); changed = true;
    }
  }
  const preserved = plan.tasks.map(task => task.id).filter(id => !descendants.has(id));
  assert.equal(descendants.size, 9);
  assert.deepEqual(preserved, ['requirements', 'data-contract', 'interaction-plan']);
  const rebuilt = artifacts.filter(artifact => artifact.content.generation === 2).map(artifact => artifact.content.taskId);
  assert.deepEqual(new Set(rebuilt), descendants);
  assert.equal(rebuilt.length, 9);
  for (const taskId of preserved) {
    const versions = artifacts.filter(artifact => artifact.content.taskId === taskId);
    assert.equal(versions.length, 1);
    assert.equal(versions[0].content.generation, 1);
  }

  const fixtureSource = fs.readFileSync(path.join(packageRoot, 'examples/release-lab.json'), 'utf8');
  assert.equal(plan.sourceBindings[0].sha256, objectHash(fixtureSource));
  for (const artifact of artifacts) {
    assert.equal(artifact.sha256, objectHash(artifact.content));
    assert.match(artifact.path, /^artifacts\/[a-z0-9-]+-[12]-[1-9][0-9]*\.json$/);
  }
  const artifactHashes = new Set(artifacts.map(artifact => artifact.sha256));
  for (const event of events.filter(event => event.action.type === 'result')) assert.equal(artifactHashes.has(event.action.resultHash), true);
  const reviewHashes = new Set(reviews.map(review => objectHash(review)));
  for (const event of events.filter(event => ['accept', 'reject', 'reopen', 'resume'].includes(event.action.type))) {
    assert.equal(reviewHashes.has(event.action.reviewEvidence.sha256), true);
  }

  const rejected = injections.filter(item => item.type === 'candidate-rejected');
  assert.equal(rejected.length, 1);
  const acceptedHashes = new Set(), currentCandidate = new Map(), finalReviewByTask = new Map();
  for (const event of events) {
    const action = event.action;
    if (action.type === 'result') currentCandidate.set(action.taskId, action.resultHash);
    if (action.type === 'reject') currentCandidate.delete(action.taskId);
    if (action.type === 'accept') {
      assert.equal(currentCandidate.has(action.taskId), true);
      acceptedHashes.add(currentCandidate.get(action.taskId));
      finalReviewByTask.set(action.taskId, action.reviewEvidence.sha256);
    }
  }
  assert.equal(acceptedHashes.has(rejected[0].priorResultHash), false);
  assert.notEqual(finalState.tasks.find(task => task.id === rejected[0].taskId).resultHash, rejected[0].priorResultHash);
  for (const task of finalState.tasks) {
    assert.equal(task.status, 'accepted-candidate');
    assert.equal(artifactHashes.has(task.resultHash), true);
    assert.equal(task.review.evidenceSha256, finalReviewByTask.get(task.id));
  }

  const restart = injections.filter(item => item.type === 'serialized-restart');
  assert.deepEqual(restart, [{ type: 'serialized-restart', eventCount: 12 }]);
  const prefix = replayTeam({ schema: 'agent-workbench-replay-input-v1', plan, events: events.slice(0, 12) });
  assert.deepEqual(validateTeam(JSON.parse(JSON.stringify(prefix.state))), prefix.state);
  const replayed = replayTeam(JSON.parse(JSON.stringify({ schema: 'agent-workbench-replay-input-v1', plan, events })));
  assert.deepEqual(replayed.state, finalState);
  assert.equal(replayed.eventsApplied, 72);
  assert.equal(finalState.allCandidatesAccepted, true);
  assert.equal(finalState.runtimeAccepted, false);
});

test('CLI validate, inspect, brief, and replay emit JSON and reject unknown fields from a temporary cwd', () => {
  const { evidence } = runReleaseLab();
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'agent-workbench-cli-'));
  const files = {
    validate: evidence.finalState,
    inspect: { state: evidence.finalState, options: { maxConcurrent: 3 } },
    brief: { state: evidence.finalState, taskId: 'release-review', options: { maxBytes: 16384 } },
    replay: { schema: 'agent-workbench-replay-input-v1', plan: evidence.plan, events: evidence.events }
  };
  function run(command, filename) {
    return spawnSync(process.execPath, [cli, 'team', command, filename], { cwd: temporary, encoding: 'utf8' });
  }
  try {
    for (const [command, input] of Object.entries(files)) fs.writeFileSync(path.join(temporary, `${command}.json`), JSON.stringify(input));
    const expectedSchemas = {
      validate: 'agent-workbench-team-state-v2',
      inspect: 'agent-workbench-team-inspection-v1',
      brief: 'agent-workbench-task-brief-v1',
      replay: 'agent-workbench-replay-result-v1'
    };
    for (const command of Object.keys(files)) {
      const output = run(command, `${command}.json`);
      assert.equal(output.status, 0, output.stderr);
      assert.equal(output.stderr, '');
      assert.equal(JSON.parse(output.stdout).schema, expectedSchemas[command]);

      const invalid = structuredClone(files[command]);
      invalid.unknownField = true;
      const filename = `${command}-unknown.json`;
      fs.writeFileSync(path.join(temporary, filename), JSON.stringify(invalid));
      const rejected = run(command, filename);
      assert.equal(rejected.status, 1);
      assert.equal(rejected.stdout, '');
      const envelope = JSON.parse(rejected.stderr);
      assert.deepEqual({ ok: envelope.ok, code: envelope.code }, { ok: false, code: 'WORKBENCH_INVALID' });
      assert.match(envelope.error, /unsupported field|field count exceeds bound/);
    }
  } finally {
    fs.rmSync(temporary, { recursive: true, force: true });
  }
});

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { planTeam, advanceTeam } = require('../lib/team-state.cjs');
const { inspectTeam, buildTaskBrief } = require('../lib/team-inspector.cjs');

const sha = value => value.repeat(64);
const NOW = '2026-09-13T12:00:00.000Z';
const LATER = '2026-09-13T12:05:00.000Z';
const plan = () => planTeam({
  schema: 'agent-workbench-plan-input-v1', teamId: 'inspect-team', now: NOW, deadlineAt: '2026-09-13T12:25:00.000Z', maxTurns: 12, maxPeerHops: 2,
  sourceBindings: [{ id: 'contract', sha256: sha('a') }], acceptance: ['Bound evidence.'],
  tasks: [
    { id: 'root', ownerRoleId: 'workbench-research', objective: 'Collect source evidence.', dependsOn: [] },
    { id: 'critical', ownerRoleId: 'workbench-systems', objective: 'Implement critical path.', dependsOn: ['root'] },
    { id: 'short', ownerRoleId: 'workbench-design', objective: 'Implement independent branch.', dependsOn: ['root'] },
    { id: 'tail', ownerRoleId: 'workbench-critic', objective: 'Review critical work.', dependsOn: ['critical'] },
    { id: 'free', ownerRoleId: 'workbench-design', objective: 'Prepare independent evidence.', dependsOn: [] }
  ]
});
function action(state, action) {
  return advanceTeam({ schema: 'agent-workbench-advance-input-v1', state, expectedRevision: state.revision, expectedStateFingerprint: state.stateFingerprint, now: LATER, action }).state;
}
function bound(state, type, taskId, extra = {}) {
  return { type, taskId, sourceFingerprint: state.sourceFingerprint, criteriaFingerprint: state.criteriaFingerprint, ...extra };
}
function acceptedRoot() {
  let state = plan();
  state = action(state, bound(state, 'dispatch', 'root', { actorRoleId: 'workbench-research', dispatchId: 'root-dispatch' }));
  state = action(state, bound(state, 'result', 'root', { dispatchId: 'root-dispatch', resultHash: sha('b'), summary: 'Source evidence collected.' }));
  return action(state, bound(state, 'accept', 'root', { reviewerCapability: 'lead-reviewer', reviewEvidence: { path: 'evidence/root-review.json', sha256: sha('c') }, coordinatorAttested: true }));
}

