'use strict';

const net = require('node:net');
const { types } = require('node:util');

function fail(message) { throw new TypeError(message); }

function fields(value, label, allowed, required = allowed) {
  if (types.isProxy(value)) fail(`${label}: proxy rejected`);
  if (!value || typeof value !== 'object' || Array.isArray(value)) fail(`${label}: plain object required`);
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null) fail(`${label}: prototype rejected`);
  const keys = Reflect.ownKeys(value);
  if (keys.length > allowed.size) fail(`${label}: field count exceeds bound`);
  const result = new Map();
  for (const key of keys) {
    if (typeof key !== 'string' || !allowed.has(key)) fail(`${label}: unsupported field`);
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (!descriptor || !Object.hasOwn(descriptor, 'value')) fail(`${label}.${key}: accessor rejected`);
    result.set(key, descriptor.value);
  }
  for (const key of required) if (!result.has(key)) fail(`${label}.${key}: required`);
  return result;
}

function array(value, label, maximum, minimum = 0) {
  if (types.isProxy(value)) fail(`${label}: proxy rejected`);
  if (!Array.isArray(value) || Object.getPrototypeOf(value) !== Array.prototype) fail(`${label}: plain array required`);
  const length = Object.getOwnPropertyDescriptor(value, 'length')?.value;
  if (!Number.isInteger(length) || length < minimum || length > maximum) fail(`${label}: length outside bound`);
  const keys = Reflect.ownKeys(value);
  if (keys.length > maximum + 1) fail(`${label}: field count exceeds bound`);
  for (const key of keys) {
    if (key === 'length') continue;
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (typeof key !== 'string' || !/^(0|[1-9][0-9]*)$/.test(key) || Number(key) >= length || !descriptor || !Object.hasOwn(descriptor, 'value')) fail(`${label}: sparse, accessor, or extra field rejected`);
  }
  const result = [];
  for (let index = 0; index < length; index += 1) {
    const descriptor = Object.getOwnPropertyDescriptor(value, String(index));
    if (!descriptor) fail(`${label}: sparse array rejected`);
    result.push(descriptor.value);
  }
  return result;
}

function text(value, label, maximum) {
  if (typeof value !== 'string' || !value.trim() || value.length > maximum) fail(`${label}: invalid string`);
  return value.trim();
}

function identifier(value, label) {
  if (typeof value !== 'string' || !/^[a-z0-9][a-z0-9._-]{0,79}$/i.test(value)) fail(`${label}: invalid identifier`);
  return value;
}

function digest(value, label) {
  if (typeof value !== 'string' || !/^[a-f0-9]{64}$/.test(value)) fail(`${label}: invalid sha256`);
  return value;
}

function instant(value, label) {
  if (typeof value !== 'string') fail(`${label}: canonical timestamp required`);
  const milliseconds = Date.parse(value);
  if (!Number.isFinite(milliseconds) || new Date(milliseconds).toISOString() !== value) fail(`${label}: canonical timestamp required`);
  return { value, milliseconds };
}

function integer(value, label, minimum, maximum) {
  if (!Number.isInteger(value) || value < minimum || value > maximum) fail(`${label}: invalid integer`);
  return value;
}

function stringList(value, label, maximum, itemMaximum, minimum = 0, identifiers = false) {
  const items = array(value, label, maximum, minimum).map((item, index) => identifiers ? identifier(item, `${label}[${index}]`) : text(item, `${label}[${index}]`, itemMaximum));
  if (new Set(items).size !== items.length) fail(`${label}: duplicate entry`);
  return items;
}

function publicHttps(value, label) {
  const raw = text(value, label, 2048);
  let parsed;
  try { parsed = new URL(raw); } catch { fail(`${label}: invalid URL`); }
  if (parsed.protocol !== 'https:' || parsed.username || parsed.password || parsed.port || parsed.hash) fail(`${label}: public HTTPS URL required`);
  const host = parsed.hostname.toLowerCase();
  const unbracketed = host.startsWith('[') && host.endsWith(']') ? host.slice(1, -1) : host;
  if (/\.\.$/.test(unbracketed)) fail(`${label}: public host required`);
  const normalizedHost = unbracketed.endsWith('.') ? unbracketed.slice(0, -1) : unbracketed;
  if (!normalizedHost || normalizedHost === 'localhost' || normalizedHost.endsWith('.localhost') || normalizedHost.endsWith('.local')) fail(`${label}: public host required`);
  const ip = net.isIP(normalizedHost);
  if (ip === 4) {
    const [a, b, c] = normalizedHost.split('.').map(Number);
    if (a === 0 || a === 10 || a === 127 || a >= 224 || (a === 100 && b >= 64 && b <= 127) || (a === 169 && b === 254) || (a === 172 && b >= 16 && b <= 31) || (a === 192 && (b === 168 || (b === 0 && (c === 0 || c === 2)))) || (a === 198 && (b === 18 || b === 19 || (b === 51 && c === 100))) || (a === 203 && b === 0 && c === 113)) fail(`${label}: public host required`);
  }
  if (ip === 6 && (normalizedHost === '::' || normalizedHost === '::1' || normalizedHost.startsWith('::ffff:') || normalizedHost.startsWith('fc') || normalizedHost.startsWith('fd') || normalizedHost.startsWith('fe8') || normalizedHost.startsWith('fe9') || normalizedHost.startsWith('fea') || normalizedHost.startsWith('feb') || normalizedHost.startsWith('ff') || normalizedHost.startsWith('2001:db8:') || normalizedHost === '2001:db8::')) fail(`${label}: public host required`);
  return parsed.toString();
}

module.exports = { fail, fields, array, text, identifier, digest, instant, integer, stringList, publicHttps };

